Method.Source:
/// <summary>
/// Extends preRunAction for printing logic of subcontractor purchase order
/// </summary>
/// <param name = "_mappingRun">ERIFormatMappingRun</param>
protected void preRunAction(ERIFormatMappingRun _mappingRun)
{
    next preRunAction(_mappingRun);

    ERIFormatMappingRunWithDestinationAction avaMappingRunWithAction = _mappingRun as ERIFormatMappingRunWithDestinationAction;

    if(this.reportDataContract.parmReportName() == 'AVASCPPurchPurchaseOrder.Report'
        && this.reportRunController.parmArgs().menuItemName() == 'AVASubcontractorOrderPrintMail'
        && avaMappingRunWithAction)
    {
        avaMappingRunWithAction.withDestinationAction(ERDestinationAction::Send);
    }

    AVASplitShipConfirmUpdateContainerDisposal instance = AVASplitShipConfirmUpdateContainerDisposal::current();

    if (instance
     && avaMappingRunWithAction)
    {
        avaMappingRunWithAction.withDestinationAction(ERDestinationAction::Send);
    }
}
